<?php
require_once dirname(__DIR__).'/includes/functions.php';require_content_manager();$id=(int)($_GET['id']??0);
$s=$con->prepare("SELECT a.*,u.name,u.email,u.education_level,j.title job_title,j.company,j.career_id,c.title career_title FROM job_applications a JOIN users u ON u.id=a.user_id JOIN job_opportunities j ON j.id=a.job_id LEFT JOIN careers c ON c.id=j.career_id WHERE a.id=?");$s->bind_param('i',$id);$s->execute();$a=$s->get_result()->fetch_assoc();if(!$a){http_response_code(404);exit('Application not found');}
$s=$con->prepare('SELECT * FROM user_education WHERE user_id=? ORDER BY is_current DESC,end_year DESC');$s->bind_param('i',$a['user_id']);$s->execute();$education=$s->get_result();
$s=$con->prepare("SELECT q.title,COUNT(qa.id) attempts,MAX(ROUND(qa.score/NULLIF(qa.max_score,0)*100)) best_score,MAX(qa.passed) passed FROM quizzes q LEFT JOIN quiz_attempts qa ON qa.quiz_id=q.id AND qa.user_id=? WHERE (?=0 OR q.career_id=?) GROUP BY q.id,q.title ORDER BY q.title");$career=(int)$a['career_id'];$s->bind_param('iii',$a['user_id'],$career,$career);$s->execute();$quizzes=$s->get_result();?>
<div class="row g-4"><div class="col-lg-7"><h3 class="h4"><?=e($a['name'])?></h3><p class="text-muted"><?=e($a['email'])?> · <?=e(ucfirst($a['education_level']?:'Not specified'))?></p><div class="card p-3 mb-3"><strong><?=e($a['job_title'])?> at <?=e($a['company'])?></strong><small><?=e($a['career_title'])?></small></div><h4 class="h6">Cover letter</h4><div class="border rounded p-3 mb-3"><?=$a['cover_letter']?nl2br(e($a['cover_letter'])):'<span class="text-muted">None supplied.</span>'?></div><div class="d-flex justify-content-between"><h4 class="h6">Education</h4><a target="_blank" class="btn btn-sm btn-outline-primary" href="<?=url($a['resume_path'])?>">View submitted resume</a></div><?php foreach($education as $x):?><div class="border rounded p-2 my-2"><strong><?=e($x['qualification'])?></strong><div><?=e($x['institution'])?></div><small><?=e($x['field_of_study'])?></small></div><?php endforeach?><h4 class="h6 mt-4">Relevant quizzes</h4><table class="table table-sm"><thead><tr><th>Quiz</th><th>Attempts</th><th>Best</th><th>Result</th></tr></thead><tbody><?php foreach($quizzes as $q):?><tr><td><?=e($q['title'])?></td><td><?=$q['attempts']?></td><td><?=$q['attempts']?(int)$q['best_score'].'%':'—'?></td><td><?=$q['passed']?'Passed':($q['attempts']?'Not passed':'Not attempted')?></td></tr><?php endforeach?></tbody></table></div>
<div class="col-lg-5"><div class="card p-4 mb-3"><h3 class="h5">AI review assistant</h3><p class="small text-muted">Uses anonymised education and quiz results with job requirements. Resume contents and personal contact details are not sent. AI does not make the hiring decision.</p><button class="btn btn-outline-primary analyse-application" data-id="<?=$id?>"><i class="bi bi-stars"></i> Analyse with AI</button><div id="applicationAiResult" class="alert alert-light border mt-3 d-none"></div></div><form class="card p-4 application-review-form" action="<?=url('admin/save_application_review.php')?>" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="application_id" value="<?=$id?>"><label class="form-label">Status</label><select class="form-select mb-3" name="status"><?php foreach(['submitted','under_review','shortlisted','unsuccessful','accepted'] as $x):?><option value="<?=$x?>" <?=$a['status']===$x?'selected':''?>><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach?></select><label class="form-label">Feedback for student</label><textarea class="form-control mb-3" rows="6" maxlength="4000" name="reviewer_feedback"><?=e($a['reviewer_feedback'])?></textarea><button class="btn btn-primary">Save review</button></form></div></div>
